#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(bt_att);

/* Bounded A2 discovery diagnostics.  This is deliberately local to ATT:
 * it does not alter protocol behaviour, queue ownership, or callback ABI. */
#define BT_ATT_DIAG_CAP 128
enum bt_att_diag_kind {
	BT_ATT_DIAG_RX = 1, BT_ATT_DIAG_HANDLER, BT_ATT_DIAG_RSP,
	BT_ATT_DIAG_SEND, BT_ATT_DIAG_QUEUE, BT_ATT_DIAG_COMPLETE,
};
struct bt_att_diag_event {
	uint32_t seq;
	uint32_t t_ms;
	uint32_t generation;
	uintptr_t chan;
	uint8_t kind;
	uint8_t opcode;
	uint16_t len;
	uint16_t h1;
	uint16_t h2;
	int16_t err;
};
struct bt_att_chan;
static struct bt_att_diag_event bt_att_diag_events[BT_ATT_DIAG_CAP];
static atomic_t bt_att_diag_count;
static atomic_t bt_att_diag_dropped;
static atomic_t bt_att_diag_generation;
static atomic_t bt_att_diag_banner;
static struct bt_conn *bt_att_diag_conn;

static void bt_att_diag_record(struct bt_att_chan *chan, uint8_t kind,
				       uint8_t opcode, uint16_t len,
				       uint16_t h1, uint16_t h2, int err)
{
	int slot = atomic_inc(&bt_att_diag_count);
	if (slot < 0 || slot >= BT_ATT_DIAG_CAP) {
		atomic_inc(&bt_att_diag_dropped);
		return;
	}
	bt_att_diag_events[slot] = (struct bt_att_diag_event){
		.seq = (uint32_t)slot, .t_ms = k_uptime_get_32(),
		.generation = (uint32_t)atomic_get(&bt_att_diag_generation),
		.chan = (uintptr_t)chan,
		.kind = kind, .opcode = opcode, .len = len,
		.h1 = h1, .h2 = h2, .err = (int16_t)err,
	};
}

static void bt_att_diag_dump(void)
{
	int count = atomic_get(&bt_att_diag_count);
	int limit = MIN(count, BT_ATT_DIAG_CAP);
	int i;
	LOG_INF("A2_ATT_DUMP generation=%u count=%d dropped=%d",
		(uint32_t)atomic_get(&bt_att_diag_generation), limit,
		(int)atomic_get(&bt_att_diag_dropped));
	for (i = 0; i < limit; i++) {
		struct bt_att_diag_event *e = &bt_att_diag_events[i];
		LOG_INF("A2_ATT_EVT seq=%u t=%u gen=%u chan=%p kind=%u op=0x%02x len=%u h1=%u h2=%u err=%d",
			e->seq, e->t_ms, e->generation, (void *)e->chan, e->kind,
			e->opcode, e->len, e->h1, e->h2, e->err);
	}
	atomic_set(&bt_att_diag_count, 0);
	atomic_set(&bt_att_diag_dropped, 0);
}

#define ATT_CHAN(_ch) CONTAINER_OF(_ch, struct bt_att_chan, chan.chan)
#if defined(CONFIG_BT_ATT_OVER_BR)
#define ATT_BR_CHAN(_ch) CONTAINER_OF(_ch, struct bt_att_chan, br_chan.chan)
#endif /* CONFIG_BT_ATT_OVER_BR */
#define ATT_REQ(_node) CONTAINER_OF(_node, struct bt_att_req, node)
#endif /* CONFIG_BT_ATT_ERR_TO_STR */

static void att_tx_destroy(struct net_buf *buf)
{
	struct bt_att_tx_meta_data *p_meta = bt_att_get_tx_meta_data(buf);
	struct bt_att_tx_meta_data meta;

	LOG_DBG("%p", buf);

	/* Destroy the buffer first, as the callback may attempt to allocate a
	 * new one for another operation.
	 */
	meta = *p_meta;

	/* Clear the meta storage. This might help catch illegal
	 * "use-after-free"s. An initial memset is not necessary, as the
	 * metadata storage array is `static`.
	 */
	memset(p_meta, 0x00, sizeof(*p_meta));

	/* After this point, p_meta doesn't belong to us.
	 * The user data will be memset to 0 on allocation.
	 */
	net_buf_destroy(buf);

	/* ATT opcode 0 is invalid. If we get here, that means the buffer got
	 * destroyed before it was ready to be sent. Hopefully nobody sets the
	 * opcode and then destroys the buffer without sending it. :'(
	 */
	if (meta.opcode != 0) {
		att_on_sent_cb(&meta);
	}
}

NET_BUF_POOL_DEFINE(att_pool, CONFIG_BT_ATT_TX_COUNT,
		    BT_L2CAP_SDU_BUF_SIZE(BT_ATT_BUF_SIZE),
		    sizeof(struct bt_att_tx_meta_data), att_tx_destroy);

struct bt_att_tx_meta_data *bt_att_get_tx_meta_data(const struct net_buf *buf)
{
	__ASSERT_NO_MSG(net_buf_pool_get(buf->pool_id) == &att_pool);

	/* Metadata lifetime is implicitly tied to the buffer lifetime.
	 * Treat it as part of the buffer itself.
	 */
	return (struct bt_att_tx_meta_data *)net_buf_user_data(buf);
}

static int bt_att_chan_send(struct bt_att_chan *chan, struct net_buf *buf);

static void att_chan_mtu_updated(struct bt_att_chan *updated_chan);
static void bt_att_disconnected(struct bt_l2cap_chan *chan);

struct net_buf *bt_att_create_rsp_pdu(struct bt_att_chan *chan, uint8_t op);

static void bt_att_sent(struct bt_l2cap_chan *ch);

static void att_sent(void *user_data)
{
	struct bt_att_tx_meta_data *data = user_data;
	struct bt_att_chan *att_chan = data->att_chan;
	struct bt_conn *conn = att_chan->att->conn;
	struct bt_l2cap_chan *chan;

	__ASSERT_NO_MSG(!bt_att_is_enhanced(att_chan));

	if (IS_ENABLED(CONFIG_BT_ATT_OVER_BR) && bt_att_is_over_br(att_chan)) {
		chan = &att_chan->br_chan.chan;
	} else {
		chan = &att_chan->chan.chan;
	}

	LOG_DBG("conn %p chan %p", conn, chan);
	bt_att_diag_record(att_chan, BT_ATT_DIAG_COMPLETE, data->opcode, 0, 0, 0,
				  data->err);

	/* For EATT, `bt_att_sent` is assigned to the `.sent` L2 callback.
	 * L2CAP will then call it once the SDU has finished sending.
	 *
	 * For UATT and ATT over BR, this won't happen. Call it manually
	 * instead.
	 */
	bt_att_sent(chan);
}

