  38	/* Bounded A2 discovery diagnostics.  This is deliberately local to ATT:
  39	 * it does not alter protocol behaviour, queue ownership, or callback ABI. */
  40	#define BT_ATT_DIAG_CAP 128
  41	#define BT_ATT_DIAG_EARLY 32
  42	#define BT_ATT_DIAG_TAIL (BT_ATT_DIAG_CAP - BT_ATT_DIAG_EARLY)
  43	enum bt_att_diag_kind {
  44		BT_ATT_DIAG_RX = 1, BT_ATT_DIAG_HANDLER, BT_ATT_DIAG_RSP,
  45		BT_ATT_DIAG_SEND, BT_ATT_DIAG_QUEUE, BT_ATT_DIAG_COMPLETE,
  46	};
  47	struct bt_att_diag_event {
  48		uint32_t seq;
  49		uint32_t t_ms;
  50		uint32_t generation;
  51		uintptr_t chan;
  52		uint8_t kind;
  53		uint8_t opcode;
  54		uint16_t len;
  55		uint16_t h1;
  56		uint16_t h2;
  57		int16_t err;
  58		uint8_t prefix_len;
  59		uint8_t prefix_truncated;
  60		uint8_t prefix[8];
  61	};
  62	struct bt_att_chan;
  63	static struct bt_att_diag_event bt_att_diag_events[BT_ATT_DIAG_CAP];
  64	static struct bt_att_diag_event bt_att_diag_snapshot[BT_ATT_DIAG_CAP];
  65	static atomic_t bt_att_diag_count;
  66	static atomic_t bt_att_diag_dropped;
  67	static atomic_t bt_att_diag_total;
  68	static atomic_t bt_att_diag_early;
  69	static atomic_t bt_att_diag_tail_count;
  70	static atomic_t bt_att_diag_tail_next;
  71	static atomic_t bt_att_diag_generation;
  72	static atomic_t bt_att_diag_banner;
  73	static struct bt_conn *bt_att_diag_conn;
  74	K_MUTEX_DEFINE(bt_att_diag_lock);
  75	
  76	static void bt_att_diag_record_ex(struct bt_att_chan *chan, uint8_t kind,
  77					       uint8_t opcode, uint16_t len,
  78					       uint16_t h1, uint16_t h2, int err,
  79					       const uint8_t *prefix, uint8_t prefix_len)
  80	{
  81		int slot;
  82		uint32_t seq;
  83		k_mutex_lock(&bt_att_diag_lock, K_FOREVER);
  84		seq = (uint32_t)atomic_get(&bt_att_diag_total);
  85		atomic_inc(&bt_att_diag_total);
  86		if (atomic_get(&bt_att_diag_early) < BT_ATT_DIAG_EARLY) {
  87			slot = atomic_get(&bt_att_diag_early);
  88			atomic_inc(&bt_att_diag_early);
  89		} else {
  90			slot = BT_ATT_DIAG_EARLY + atomic_get(&bt_att_diag_tail_next);
  91			atomic_set(&bt_att_diag_tail_next,
  92				   (atomic_get(&bt_att_diag_tail_next) + 1) % BT_ATT_DIAG_TAIL);
  93			if (atomic_get(&bt_att_diag_tail_count) < BT_ATT_DIAG_TAIL) {
  94				atomic_inc(&bt_att_diag_tail_count);
  95			} else {
  96				atomic_inc(&bt_att_diag_dropped);
  97			}
  98		}
  99		if (slot < 0 || slot >= BT_ATT_DIAG_CAP) {
 100			atomic_inc(&bt_att_diag_dropped);
 101			k_mutex_unlock(&bt_att_diag_lock);
 102			return;
 103		}
 104		atomic_set(&bt_att_diag_count, MIN(BT_ATT_DIAG_CAP,
 105							 atomic_get(&bt_att_diag_count) + 1));
 106		bt_att_diag_events[slot] = (struct bt_att_diag_event){
 107			.seq = seq, .t_ms = k_uptime_get_32(),
 108			.generation = (uint32_t)atomic_get(&bt_att_diag_generation),
 109			.chan = (uintptr_t)chan,
 110			.kind = kind, .opcode = opcode, .len = len,
 111			.h1 = h1, .h2 = h2, .err = (int16_t)err,
 112		};
 113		bt_att_diag_events[slot].prefix_len = MIN(prefix_len, 8);
 114		bt_att_diag_events[slot].prefix_truncated = prefix_len > 8;
 115		if (prefix && bt_att_diag_events[slot].prefix_len)
 116			memcpy(bt_att_diag_events[slot].prefix, prefix,
 117			       bt_att_diag_events[slot].prefix_len);
 118		k_mutex_unlock(&bt_att_diag_lock);
 119	}
