 121	static void bt_att_diag_record(struct bt_att_chan *chan, uint8_t kind,
 122					       uint8_t opcode, uint16_t len,
 123					       uint16_t h1, uint16_t h2, int err)
 124	{
 125		bt_att_diag_record_ex(chan, kind, opcode, len, h1, h2, err, NULL, 0);
 126	}
