 128	static void bt_att_diag_dump(void)
 129	{
 130		int count;
 131		int dropped;
 132		uint32_t generation;
 133		int limit;
 134		int early_count;
 135		int tail_count;
 136		int tail_next;
 137		int i;
 138		k_mutex_lock(&bt_att_diag_lock, K_FOREVER);
 139		count = atomic_get(&bt_att_diag_count);
 140		limit = MIN(count, BT_ATT_DIAG_CAP);
 141		dropped = atomic_get(&bt_att_diag_dropped);
 142		generation = (uint32_t)atomic_get(&bt_att_diag_generation);
 143		early_count = atomic_get(&bt_att_diag_early);
 144		tail_count = atomic_get(&bt_att_diag_tail_count);
 145		tail_next = atomic_get(&bt_att_diag_tail_next);
 146		memcpy(bt_att_diag_snapshot, bt_att_diag_events,
 147		       sizeof(bt_att_diag_snapshot));
 148		atomic_set(&bt_att_diag_count, 0);
 149		atomic_set(&bt_att_diag_dropped, 0);
 150		atomic_set(&bt_att_diag_total, 0);
 151		atomic_set(&bt_att_diag_early, 0);
 152		atomic_set(&bt_att_diag_tail_count, 0);
 153		atomic_set(&bt_att_diag_tail_next, 0);
 154		k_mutex_unlock(&bt_att_diag_lock);
 155		syslog(LOG_INFO, "A4_ATT_DUMP generation=%u count=%d dropped=%d\n",
 156		       generation, limit, dropped);
 157		for (i = 0; i < early_count; i++) {
 158			struct bt_att_diag_event *e = &bt_att_diag_snapshot[i];
 159			syslog(LOG_INFO, "A4_ATT_EVT seq=%u t=%u gen=%u chan=%p kind=%u op=0x%02x len=%u h1=%u h2=%u err=%d prefix_len=%u trunc=%u p=%02x%02x%02x%02x%02x%02x%02x%02x\n",
 160				e->seq, e->t_ms, e->generation, (void *)e->chan, e->kind,
 161				e->opcode, e->len, e->h1, e->h2, e->err,
 162				e->prefix_len, e->prefix_truncated, e->prefix[0], e->prefix[1],
 163				e->prefix[2], e->prefix[3], e->prefix[4], e->prefix[5],
 164				e->prefix[6], e->prefix[7]);
 165		}
 166		if (dropped) {
 167			syslog(LOG_INFO, "A4_ATT_GAP omitted=%d (early events and tail retained)\n", dropped);
 168		}
 169		/* Tail slots are emitted in chronological ring order. */
 170		for (i = 0; i < tail_count; i++) {
 171			int ring = (tail_next - tail_count + i + BT_ATT_DIAG_TAIL) % BT_ATT_DIAG_TAIL;
 172			struct bt_att_diag_event *e = &bt_att_diag_snapshot[BT_ATT_DIAG_EARLY + ring];
 173			syslog(LOG_INFO, "A4_ATT_EVT seq=%u t=%u gen=%u chan=%p kind=%u op=0x%02x len=%u h1=%u h2=%u err=%d prefix_len=%u trunc=%u p=%02x%02x%02x%02x%02x%02x%02x%02x\n",
 174				e->seq, e->t_ms, e->generation, (void *)e->chan, e->kind,
 175				e->opcode, e->len, e->h1, e->h2, e->err,
 176				e->prefix_len, e->prefix_truncated, e->prefix[0], e->prefix[1],
 177				e->prefix[2], e->prefix[3], e->prefix[4], e->prefix[5],
 178				e->prefix[6], e->prefix[7]);
 179		}
 180	}
