1464	static void sc_process(struct k_work *work)
1465	{
1466		struct k_work_delayable *dwork = k_work_delayable_from_work(work);
1467		struct gatt_sc *sc = CONTAINER_OF(dwork, struct gatt_sc, work);
1468		uint16_t sc_range[2];
1469	
1470		__ASSERT(!atomic_test_bit(sc->flags, SC_INDICATE_PENDING),
1471			 "Indicate already pending");
1472	
1473		LOG_DBG("start 0x%04x end 0x%04x", sc->start, sc->end);
1474	
1475		sc_range[0] = sys_cpu_to_le16(sc->start);
1476		sc_range[1] = sys_cpu_to_le16(sc->end);
1477	
1478		atomic_clear_bit(sc->flags, SC_RANGE_CHANGED);
1479		sc->start = 0U;
1480		sc->end = 0U;
1481	
1482		sc->params.attr = &_1_gatt_svc.attrs[2];
1483		sc->params.func = sc_indicate_rsp;
1484		sc->params.data = &sc_range[0];
1485		sc->params.len = sizeof(sc_range);
1486	#if defined(CONFIG_BT_EATT)
1487		sc->params.chan_opt = BT_ATT_CHAN_OPT_NONE;
1488	#endif /* CONFIG_BT_EATT */
1489	
1490		{
1491			int submit_err = bt_gatt_indicate(NULL, &sc->params);
1492			syslog(LOG_INFO, "A4_SC_SUBMIT start=0x%04x end=0x%04x err=%d pending_before=%u\n",
1493			       sc_range[0], sc_range[1], submit_err,
1494			       atomic_test_bit(sc->flags, SC_INDICATE_PENDING));
1495			if (submit_err) {
1496			/* No connections to indicate */
1497			return;
1498			}
1499		}
1500	
1501		atomic_set_bit(sc->flags, SC_INDICATE_PENDING);
1502	}
