1746	static void sc_indicate(struct bt_dev *hdev, uint16_t start, uint16_t end)
1747	{
1748	#if defined(CONFIG_BT_GATT_DYNAMIC_DB) ||                                                          \
1749		(defined(CONFIG_BT_GATT_CACHING) && defined(CONFIG_BT_SETTINGS))
1750		LOG_DBG("start 0x%04x end 0x%04x", start, end);
1751		syslog(LOG_INFO, "A4_SC_RANGE start=0x%04x end=0x%04x pending=%u changed=%u\n",
1752		       start, end,
1753		       atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, SC_INDICATE_PENDING),
1754		       atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, SC_RANGE_CHANGED));
1755	
1756		if (!atomic_test_and_set_bit(hdev->gatt_ctx->gatt_sc.flags, SC_RANGE_CHANGED)) {
1757			hdev->gatt_ctx->gatt_sc.start = start;
1758			hdev->gatt_ctx->gatt_sc.end = end;
1759			goto submit;
1760		}
1761	
1762		if (!update_range(&hdev->gatt_ctx->gatt_sc.start, &hdev->gatt_ctx->gatt_sc.end, start, end)) {
1763			return;
1764		}
1765	
1766	submit:
1767		if (atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, SC_INDICATE_PENDING)) {
1768			LOG_DBG("indicate pending, waiting until complete...");
1769			syslog(LOG_INFO, "A4_SC_PENDING start=0x%04x end=0x%04x\n", start, end);
1770			return;
1771		}
1772	
1773		/* Reschedule since the range has changed */
1774		sc_work_submit(hdev, SC_TIMEOUT);
1775	#endif /* BT_GATT_DYNAMIC_DB || (BT_GATT_CACHING && BT_SETTINGS) */
1776	}
